	$invalid=dp_panel_pdo_operation_record('invalid-json');$data=$invalid->jsonSerialize();$handle=fopen('php://memory','r');$data['payload']=$handle;$t->nonPublic($invalid)->writeProperty('data',$data);$encoding=dp_panel_pdo_operations_fixture($t,'encoding',['table_prefix'=>'op_encoding']);$encoding['store']->installSchema();dp_panel_pdo_operation_error($t,static fn()=>$encoding['store']->create($invalid),'record_invalid');fclose($handle);
})->tag('panel','operations','pdo','validation','exact-coverage')->maxMillis(10000);
